#!/usr/bin/env node
/* Books-2 VASC2: vascular + CTVS wave 2, FILL GAPS ONLY (own words, no textbooks).
 * Grounded in named standard sources only: SVS and ESVS guidelines, ACC/AHA and
 * ESC guidance, STS and EACTS guidance, NICE where it covers the point, ATLS for
 * trauma order, Indian practice labelled (NVBDCP filariasis programme, THOTA and
 * NOTTO transplant rules), landmark trials named correctly (ACST, SYNTAX, EXCEL,
 * PARTNER, BEST-CLI, BASIL-2, EVAR-1, CaVenT, ATTRACT, JCOG0802, CALGB, CROSS,
 * MIST, COAPT, FREEDOM, ART, ROOBY, CORONARY, NASCET, CREST). No milligram
 * regimens anywhere; every threshold is tied to a named guideline and recorded in
 * the item source field. 9 taxonomy gaps, 90 MCQs bk2-vas-051..140.
 * Modules (1)-(8) reuse their committed prep/lessons/v1 lessons, verified here
 * with LP.checkLesson and NEVER rewritten. KB reuse with disclosure (all files
 * inspected before citing, each passes scripts/kb_validate_v2.py):
 *  sur-arterial -> peripheral_arterial_disease, buerger_disease,
 *    raynaud_phenomenon, thoracic_outlet_syndrome;
 *  sur-aneurysm -> abdominal_aortic_aneurysms_evar_and_carotid_endarterectomy,
 *    popliteal_artery_aneurysm, carotid_artery_stenosis;
 *  sur-venous -> chronic_venous_insufficiency,
 *    chronic_venous_disease_ceap_and_endovenous_ablation,
 *    deep_venous_thrombosis_and_pulmonary, venous_leg_ulcer, diabetic_foot_ulcer;
 *  sur-lymphatic -> lymphedema,
 *    lymphedema_staging_lymphoscintigraphy_and_surgical_restoration, filariasis,
 *    primary_lymphoedema;
 *  sur-thoracic -> thoracic_oncology_lobectomy_and_pleural_empyema,
 *    empyema_thoracic, tension_pneumothorax, disorders_of_the_mediastinum,
 *    thymoma;
 *  sur-cardiac -> cardiac_surgery_cabg_valvular_repair_and_cardiopulmonary_bypass,
 *    valvular_heart_disease_and_endocarditis;
 *  sur-chest-trauma -> flail_chest,
 *    thoracic_trauma_tension_pneumothorax_and_tamponade, tension_pneumothorax;
 *  sur-neck-face-trauma -> neck_and_maxillofacial_trauma_zones_and_management,
 *    carotid_artery_stenosis.
 * Module (9) sgs-vascular-transplant has NO lesson, so this script writes one
 * FULL new v1 lesson plus one NEW KB v2 page
 * (sgs_vascular_graft_surveillance_transplant_workup), kept clear of
 * sur-transplant (HLA, rejection classes, renal technique) and sva-venous-access
 * (fistula sixes rule): it covers bypass graft surveillance with transplant
 * workup basics at general-surgery depth.
 * Overlay subject: surgery (already in the maikbook2 test loop). */
import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";
const require = createRequire(import.meta.url);
const LP = require("../prep-lessons.js");
const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
function mcq(id, q, o, a, exp, r, kp, source) { return { id, q, o, a, exp, r, kp, source }; }
function step(tx, say, vis) { return vis ? { tx, say, vis: null } : { tx, say, vis: null }; }
const G = [];
function gap(id, kbReuse, mcqs) { G.push({ id, kbReuse, steps: null, mcqs }); }
const N = [];
function add(id, title, REF, kb, kbName, aliases, system, specialty, steps, pearls, patho, diffs, invs, mcqs) { N.push({ id, title, REF, kb, kbName, aliases, system, specialty, steps, pearls, patho, diffs, invs, mcqs }); }

